#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>

bool nearly_equal(double a, double b) {
    const double rel = 1e-9;
    const double abs_tol = 1e-12;
    const double scale = std::max(std::abs(a), std::abs(b));
    return std::abs(a - b) <= std::max(abs_tol, rel * scale);
}

int main() {
    int n = 0;
    std::cin >> n;
    std::cout << std::setprecision(17) << std::boolalpha;
    for (int i = 0; i < n; ++i) {
        double qty = 0.0;
        double price = 0.0;
        double reported = 0.0;
        std::cin >> qty >> price >> reported;
        const double notional = qty * price;
        std::cout << notional << ' ' << (notional == reported) << ' '
                  << nearly_equal(notional, reported) << '\n';
    }
    return 0;
}

