#include <iomanip>
#include <iostream>

int main() {
    int n = 0;
    double fee = 0.0;
    std::cin >> n >> fee;
    double naive = 0.0;
    double sum = 0.0;
    double comp = 0.0;  // the low bits each add lost, negated
    for (int i = 0; i < n; ++i) {
        naive += fee;
        const double y = fee - comp;
        const double t = sum + y;
        comp = (t - sum) - y;
        sum = t;
    }
    std::cout << std::setprecision(17);
    std::cout << "naive " << naive << '\n';
    std::cout << "kahan " << sum << '\n';
    std::cout << (1e16 + 1.0) + 1.0 << ' ' << 1e16 + (1.0 + 1.0) << '\n';
    return 0;
}

