#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>

int64_t to_ticks(double price, double tick_size) {
    return std::llround(price / tick_size);
}

int64_t bid_ticks(double price, double tick_size) {  // round down onto the grid
    return static_cast<int64_t>(std::floor(price / tick_size + 1e-6));
}

int64_t ask_ticks(double price, double tick_size) {  // round up onto the grid
    return static_cast<int64_t>(std::ceil(price / tick_size - 1e-6));
}

int main() {
    int cast_wrong = 0;
    int llround_wrong = 0;
    for (int64_t cents = 0; cents < 100000; ++cents) {
        const double price = cents / 100.0;  // 0.00 to 999.99, as a feed sends them
        if (static_cast<int64_t>(price / 0.01) != cents) {
            ++cast_wrong;
        }
        if (to_ticks(price, 0.01) != cents) {
            ++llround_wrong;
        }
    }
    std::cout << "wrong: cast " << cast_wrong << ", llround " << llround_wrong << '\n';

    double tick_size = 0.0;
    double edge = 0.0;
    int n = 0;
    std::cin >> tick_size >> edge >> n;
    std::cout << std::fixed << std::setprecision(2);
    for (int i = 0; i < n; ++i) {
        double fair = 0.0;
        std::cin >> fair;
        const int64_t bid = bid_ticks(fair - edge, tick_size);
        const int64_t ask = ask_ticks(fair + edge, tick_size);
        std::cout << bid << ' ' << ask << ' ' << bid * tick_size << ' ' << ask * tick_size << '\n';
    }
    return 0;
}

