    int n = 0;
    std::cin >> n;
    __int128 total = 0;
    for (int i = 0; i < n; ++i) {
        int64_t price_nanos = 0;  // dollars times 10^9
        int64_t qty = 0;
        std::cin >> price_nanos >> qty;
        int64_t notional = 0;
        if (__builtin_mul_overflow(price_nanos, qty, &notional)) {
            std::cout << "overflow\n";
        } else {
            std::cout << notional << '\n';
        }
        total += static_cast<__int128>(price_nanos) * qty;
    }
    const int64_t dollars = static_cast<int64_t>(total / 1'000'000'000);
    std::cout << "total $" << dollars << '\n';
    return 0;
}

